-- ===== REGLAS SLA (área + prioridad + categoría) =====
-- Una regla por combinación (área × prioridad × categoría) para que todo ticket tenga SLA.
INSERT INTO sla_rule (sla_policy_id, area_id, priority_id, category_id, active_sla_rule)
SELECT slp.id_sla_policy, ar.id_area, pr.id_priority, ct.id_category, TRUE
FROM sla_policy slp
CROSS JOIN area ar
CROSS JOIN priority pr
CROSS JOIN category ct
WHERE ct.deleted_category = FALSE
  AND slp.name_sla_policy = CASE
        WHEN pr.name_priority = 'CRITICA' THEN 'SLA Crítico'
        WHEN pr.name_priority = 'ALTA'    THEN 'SLA Alto'
        WHEN pr.name_priority = 'MEDIA'   THEN 'SLA Medio'
        ELSE 'SLA Bajo'
    END
ON CONFLICT DO NOTHING;

-- ===== USUARIOS ADMINISTRATIVOS =====
-- Los usuarios administrativos NO se crean aqui a proposito. Una contrasena
-- fija dentro del repositorio es una contrasena publica para cualquiera que
-- lea el codigo o clonee el proyecto, y estos cuentas tienen el control total
-- del sistema. Los crea AdminSeedInitializer al arrancar, tomando la clave de
-- la variable de entorno ADMIN_SEED_PASSWORD, y los marca con
-- must_change_password=TRUE para que la cambien obligatoriamente en el primer
-- login. Si ADMIN_SEED_PASSWORD llega vacia no se crea ninguna cuenta
-- administrativa: en produccion el primer SUPER_ADMIN se da de alta con esa
-- variable definida, o a mano desde consola.
--
-- Los usuarios de prueba (agente / usuario) viven en data-dev.sql, que solo se
-- carga con el perfil "dev".


-- ===== RELACION USUARIOS-EQUIPOS =====
-- En el primer arranque esto no encuentra usuarios (se crean despues, en Java),
-- asi que no hace nada. En los arranques siguientes ya recoge a los
-- administrativos sembrados y los mete en el equipo TI.
INSERT INTO team_user (team_id, user_id, active_team_user)
SELECT t.id_team, u.id_user, TRUE
FROM support_team t CROSS JOIN users u
WHERE t.name_team = 'Equipo TI' 
  AND u.corporate_email_user IN ('superadmin@coacmagisterio.fin.ec','admin@coacmagisterio.fin.ec')
ON CONFLICT (team_id, user_id) DO NOTHING;

