     '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">Restablecimiento de contraseña</h2><p>Estimado/a <b>[nombre]</b>:</p><p>Se ha restablecido su contraseña. Su <b>contraseña temporal</b> de acceso es:</p><div style="margin:18px 0;padding:16px;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:8px;font-size:20px;font-weight:bold;text-align:center;letter-spacing:1px;color:#062e86;">[password]</div><p>Al iniciar sesión deberá cambiarla por una contraseña personalizada.</p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>', TRUE, 'DEFAULT', NULL)
ON CONFLICT (name_template) DO NOTHING;

-- Actualiza las plantillas de envío de clave si aún no traen el diseño estándar
-- (con cabecera azul y [logo]); si el usuario ya las personalizó al nuevo diseño no se tocan
UPDATE notification_template
SET body_template = '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">Restablecimiento de contraseña</h2><p>Estimado/a <b>[nombre]</b>:</p><p>Se ha restablecido su contraseña. Su <b>contraseña temporal</b> de acceso es:</p><div style="margin:18px 0;padding:16px;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:8px;font-size:20px;font-weight:bold;text-align:center;letter-spacing:1px;color:#062e86;">[password]</div><p>Al iniciar sesión deberá cambiarla por una contraseña personalizada.</p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>'
WHERE name_template = 'RESET_PASSWORD'
  AND body_template LIKE '%>Mesa de Ayuda COAC</p>%'
  AND custom_template = FALSE;

UPDATE notification_template
SET body_template = '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">Bienvenido/a a Mesa de Servicios</h2><p>Estimado/a <b>[nombre]</b>:</p><p>Se ha creado su cuenta de acceso. Su <b>contraseña temporal</b> es:</p><div style="margin:18px 0;padding:16px;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:8px;font-size:20px;font-weight:bold;text-align:center;letter-spacing:1px;color:#062e86;">[password]</div><p>Al iniciar sesión deberá cambiarla por una contraseña personalizada.</p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>'
WHERE name_template = 'CREACION_USUARIO'
  AND body_template LIKE '%>Mesa de Ayuda COAC</p>%'
  AND custom_template = FALSE;

-- Estándariza el resto de plantillas con el mismo armazón (cabecera azul con [logo] y pie)
UPDATE notification_template
SET body_template =
  '<div style="background:#f3f4f6;padding:32px 16px;"><div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;"><div style="background:#062e86;padding:24px 32px;text-align:center;">[logo]</div><div style="padding:28px 36px 12px;font-family:Arial,Helvetica,sans-serif;color:#374151;"><h2 style="color:#062e86;margin:0 0 18px;">'
  || CASE name_template
       WHEN 'TICKET_CREADO'     THEN 'Ticket #[id] creado'
       WHEN 'TICKET_ASIGNADO'   THEN 'Ticket #[id] asignado'
       WHEN 'TICKET_ACTUALIZADO' THEN 'Ticket #[id] actualizado'
       WHEN 'TICKET_RESUELTO'   THEN 'Ticket #[id] resuelto'
       WHEN 'TICKET_CERRADO'    THEN 'Ticket #[id] cerrado'
       WHEN 'RATING_REQUEST'    THEN 'Califique su ticket #[id]'
       WHEN 'SLA_WARNING'       THEN 'SLA por vencer - Ticket #[id]'
       WHEN 'SLA_BREACHED'      THEN 'SLA vencido - Ticket #[id]'
       WHEN 'ESCALATION'        THEN 'Ticket #[id] escalado'
       WHEN 'MONTHLY_EVALUATION' THEN 'Evaluación mensual disponible'
       WHEN 'TASK_ASIGNADA'     THEN 'Nueva tarea asignada'
       ELSE 'Notificación'
     END
  || '</h2><p>'
  || CASE name_template
       WHEN 'TICKET_CREADO'     THEN 'Estimado/a <b>[nombre]</b>, su ticket ha sido creado correctamente.'
       WHEN 'TICKET_ASIGNADO'   THEN 'El ticket #[id] ha sido asignado al agente <b>[agente]</b>.'
       WHEN 'TICKET_ACTUALIZADO' THEN 'Su ticket #[id] ha sido actualizado.'
       WHEN 'TICKET_RESUELTO'   THEN 'Su ticket #[id] ha sido resuelto.'
       WHEN 'TICKET_CERRADO'    THEN 'Su ticket #[id] ha sido cerrado.'
       WHEN 'RATING_REQUEST'    THEN 'Le invitamos a calificar la atención recibida en su ticket #[id].'
       WHEN 'SLA_WARNING'       THEN 'El SLA del ticket #[id] está al 80% del tiempo establecido.'
       WHEN 'SLA_BREACHED'      THEN 'El SLA del ticket #[id] se ha vencido.'
       WHEN 'ESCALATION'        THEN 'El ticket #[id] ha sido escalado para su atención.'
       WHEN 'MONTHLY_EVALUATION' THEN 'Su evaluación mensual está disponible. Ingrese al sistema para completarla.'
       WHEN 'TASK_ASIGNADA'     THEN 'Se le ha asignado una tarea. Revise el detalle de fecha y hora acordada.'
       ELSE 'Notificación del sistema.'
     END
  || '</p></div><div style="background:#062e86;padding:20px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:6px 0 0;color:#aec0dd;font-size:11px;">© 2026 COAC Magisterio de Pichincha. Todos los derechos reservados.</p></div></div><p style="max-width:620px;margin:12px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></div>'
WHERE name_template IN ('TICKET_CREADO','TICKET_ASIGNADO','TICKET_ACTUALIZADO','TICKET_RESUELTO','TICKET_CERRADO','RATING_REQUEST','SLA_WARNING','SLA_BREACHED','ESCALATION','MONTHLY_EVALUATION','TASK_ASIGNADA')
  AND body_template NOT LIKE '%max-width:620px%'
  -- Sin esta condición, una plantilla personalizada desde /admin/templates
  -- (custom_template = TRUE) cuyo diseño no llevara ese max-width exacto se
  -- sobrescribía cada vez que este script repetible volvía a ejecutarse.
  AND custom_template = FALSE;

-- Actualiza el destinatario de plantillas ya existentes sin pisar configuraciones previas
UPDATE notification_template SET recipient_rule = 'SOLICITANTE' WHERE name_template IN ('TICKET_CREADO','TICKET_ACTUALIZADO','TICKET_RESUELTO','TICKET_CERRADO','RATING_REQUEST') AND custom_template = FALSE;
UPDATE notification_template SET recipient_rule = 'AGENTE'      WHERE name_template IN ('TICKET_ASIGNADO','SLA_WARNING','SLA_BREACHED') AND custom_template = FALSE;

-- ===== ICONO Y COLOR DE LAS PLANTILLAS =====
-- El icono identifica la función (creación de ticket, SLA, cuenta, etc.) y se
-- muestra en el badge y en el selector de plantillas del escalamiento.
UPDATE notification_template SET icon_template = 'fa-solid fa-ticket',       color_template = '#2563EB' WHERE name_template = 'TICKET_CREADO'      AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-user-check',   color_template = '#0E7490' WHERE name_template = 'TICKET_ASIGNADO'    AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-arrows-rotate', color_template = '#4F46E5' WHERE name_template = 'TICKET_ACTUALIZADO' AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-circle-check', color_template = '#16A34A' WHERE name_template = 'TICKET_RESUELTO'    AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-lock',         color_template = '#334155' WHERE name_template = 'TICKET_CERRADO'     AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-star',         color_template = '#CA8A04' WHERE name_template = 'RATING_REQUEST'     AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-hourglass-half', color_template = '#D97706' WHERE name_template = 'SLA_WARNING'    AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-triangle-exclamation', color_template = '#DC2626' WHERE name_template = 'SLA_BREACHED' AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-arrow-up-right-from-square', color_template = '#B91C1C' WHERE name_template = 'ESCALATION' AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-clipboard-check', color_template = '#7C3AED' WHERE name_template = 'MONTHLY_EVALUATION' AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-list-check',   color_template = '#0891B2' WHERE name_template = 'TASK_ASIGNADA'     AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-user-plus',    color_template = '#15803D' WHERE name_template = 'CREACION_USUARIO'  AND (icon_template IS NULL OR color_template IS NULL);
UPDATE notification_template SET icon_template = 'fa-solid fa-key',          color_template = '#B45309' WHERE name_template = 'RESET_PASSWORD'    AND (icon_template IS NULL OR color_template IS NULL);
-- ===== DISEÑO DEFINITIVO DE LAS PLANTILLAS DE CORREO =====
-- Los cuerpos de arriba son de reserva:(seed). Estos son los que hay en
-- uso, generados desde la base de datos y sin los botones de redireccionamiento
-- (los <a> con display:inline-block y su tabla de una celda), porque el
-- destinatario los abre desde el correo y no puede entrar al sistema desde ahí.
-- El nombre de destino lo pone el backend con el nombre de Outlook.
-- Se aplican al final para que manden sobre cualquier texto de reserva.
UPDATE notification_template SET body_template = '[nombre] escribió en su ticket #[id] - [titulo].' WHERE name_template = 'CHAT_MENSAJE' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- Contenedor principal --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <!-- Logo --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento --> <tr> <td style="background:#ec9811;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de bienvenida --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#062e86;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ✉️ Bienvenido/a </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Tu cuenta ha sido creada </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Se ha creado tu cuenta de acceso a la <b>Mesa de Servicios</b>. A continuación encontrarás tu contraseña temporal para iniciar sesión: </p> <!-- Bloque de contraseña --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f9fafb;border:2px dashed #062e86;border-radius:10px;padding:20px;text-align:center;"> <p style="margin:0 0 8px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:1px;font-weight:bold;"> Contraseña temporal </p> <p style="margin:0;font-family:''Courier New'',Consolas,monospace;font-size:24px;font-weight:bold;color:#062e86;letter-spacing:3px;word-break:break-all;"> [password] </p> </td> </tr> </table> <!-- Alerta de seguridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #ec9811;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⚠️ Importante:</b> Por seguridad, al iniciar sesión por primera vez deberás cambiar esta contraseña por una personalizada. </p> </td> </tr> </table> <!-- Pasos --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Cómo acceder: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">1.</b> Ingresa al sistema con tu correo corporativo. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">2.</b> Usa la contraseña temporal que aparece arriba. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">3.</b> Cambia tu contraseña desde <b>Mi Perfil → Cambiar Contraseña</b>. </td> </tr> </table> <!-- Botón CTA (opcional, si tienes URL del login) --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlLogin]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ingresar al sistema</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Si tienes problemas para acceder, contacta al equipo de TI respondiendo a este correo o abriendo un ticket en el sistema. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Si no solicitaste esta cuenta, ignora este correo. </p> </td> </tr> </table></div>' WHERE name_template = 'CREACION_USUARIO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (rojo para escalado) --> <tr> <td style="background:#dc2626;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de escalado --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#fef2f2;border:1px solid #fecaca;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#dc2626;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ⚠️ Ticket escalado </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> escalado </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> El siguiente ticket ha sido <b>escalado</b> para su atención prioritaria: </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <tr> <td style="padding:4px 0;width:40%;"> <b style="color:#374151;">Solicitante:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{solicitante}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Área:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{area}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Categoría:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{categoria}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Estado:</b> </td> <td style="padding:4px 0;"> <span style="display:inline-block;padding:3px 10px;background:#fef3c7;color:#92400e;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Fecha de escalado:</b> </td> <td style="padding:4px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaEscalado}} </td> </tr> </table> </td> </tr> </table> <!-- Motivo del escalado --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>Motivo del escalado:</b> {{motivo}} </p> </td> </tr> </table> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Próximos pasos: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">1.</b> Revisa el ticket y su historial completo en el sistema. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">2.</b> Atiende el caso con la prioridad indicada. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">3.</b> Actualiza el estado del ticket cuando esté resuelto. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#dc2626" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ver ticket escalado</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Si no puedes atender este ticket, por favor reasígnalo a otro agente del equipo. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tienes tickets asignados o estás en el flujo de escalado. </p> </td> </tr> </table></div>' WHERE name_template = 'ESCALATION' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (naranja/amarillo) --> <tr> <td style="background:#ec9811;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de evaluación --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#fff7ed;border:1px solid #fed7aa;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#c2410c;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ⭐ Evaluación mensual </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Tu evaluación de <span style="color:#ec9811;">{{mes}}</span> está lista </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Tu evaluación mensual correspondiente a <b>{{mes}} {{anio}}</b> ya está disponible. Revisa tus métricas de desempeño y completa tu autoevaluación. </p> <!-- Tarjeta con resumen de métricas --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:22px;"> <p style="margin:0 0 16px;color:#062e86;font-size:13px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 📊 Resumen del mes </p> <!-- Grid de métricas --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <!-- Fila 1: Tickets cerrados + SLA --> <tr> <td style="width:50%;padding:0 6px 12px 0;vertical-align:top;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <tr> <td style="padding:14px;text-align:center;"> <p style="margin:0 0 4px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;font-weight:bold;"> Tickets cerrados </p> <p style="margin:0;color:#062e86;font-size:24px;font-weight:bold;line-height:1;"> {{ticketsCerrados}} </p> </td> </tr> </table> </td> <td style="width:50%;padding:0 0 12px 6px;vertical-align:top;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <tr> <td style="padding:14px;text-align:center;"> <p style="margin:0 0 4px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;font-weight:bold;"> Cumplimiento SLA </p> <p style="margin:0;color:#16a34a;font-size:24px;font-weight:bold;line-height:1;"> {{sla}}% </p> </td> </tr> </table> </td> </tr> <!-- Fila 2: Satisfacción + Tiempo promedio --> <tr> <td style="width:50%;padding:0 6px 0 0;vertical-align:top;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <tr> <td style="padding:14px;text-align:center;"> <p style="margin:0 0 4px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;font-weight:bold;"> Satisfacción </p> <p style="margin:0;color:#ec9811;font-size:24px;font-weight:bold;line-height:1;"> ⭐ {{satisfaccion}} </p> </td> </tr> </table> </td> <td style="width:50%;padding:0 0 0 6px;vertical-align:top;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <tr> <td style="padding:14px;text-align:center;"> <p style="margin:0 0 4px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;font-weight:bold;"> Tiempo promedio </p> <p style="margin:0;color:#3b82f6;font-size:24px;font-weight:bold;line-height:1;"> {{tiempoPromedio}}h </p> </td> </tr> </table> </td> </tr> </table> </td> </tr> </table> <!-- Alerta de plazo --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #ec9811;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⏰ Plazo:</b> Tienes hasta el <b>{{fechaLimite}}</b> para revisar y completar tu evaluación. </p> </td> </tr> </table> <!-- Qué incluye la evaluación --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> La evaluación incluye: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#ec9811;">✓</b> Autoevaluación de tu desempeño del mes. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#ec9811;">✓</b> Revisión de tus métricas y cumplimiento de SLA. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#ec9811;">✓</b> Comentarios y sugerencias para la mejora continua. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#ec9811;">✓</b> Objetivos y metas para el próximo mes. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlDashboard]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ir a mi dashboard</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Puedes acceder a tu evaluación en cualquier momento desde <b>Mi Perfil → Mis evaluaciones</b>. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Si tienes preguntas sobre tu evaluación, contacta a tu supervisor. </p> </td> </tr> </table></div>' WHERE name_template = 'MONTHLY_EVALUATION' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:32px 16px;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (verde éxito) --> <tr> <td style="background:#16a34a;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de éxito --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#166534;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ✅ Configuración correcta </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> ¡El envío de correo funciona correctamente! </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Este mensaje confirma que la <b>configuración SMTP</b> y la integración con <b>Microsoft Graph</b> están funcionando correctamente. Los correos del sistema se enviarán sin problemas a partir de ahora. </p> <!-- Tarjeta de detalles del envío --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <p style="margin:0 0 16px;color:#062e86;font-size:13px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 📋 Detalles del envío </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;"> <!-- Fecha --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha y hora: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fecha}} {{hora}} </td> </tr> <!-- Usuario --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Usuario: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{nombre}} </td> </tr> <!-- Correo destino --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📧</span> Correo destino: </b> </td> <td style="padding:6px 0;color:#4b5563;word-break:break-all;"> {{email}} </td> </tr> <!-- Host SMTP --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🌐</span> Servidor SMTP: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{host}} : {{puerto}} </td> </tr> <!-- Seguridad --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🔒</span> Seguridad: </b> </td> <td style="padding:6px 0;"> <span style="display:inline-block;padding:3px 10px;background:#dcfce7;color:#166534;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{tls}} </span> </td> </tr> <!-- Remitente --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">✉️</span> Remitente: </b> </td> <td style="padding:6px 0;color:#4b5563;word-break:break-all;"> {{fromAddress}} </td> </tr> </table> </td> </tr> </table> <!-- Alerta de éxito --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f0fdf4;border-left:4px solid #16a34a;border-radius:6px;padding:14px 16px;"> <p style="margin:0 0 6px;color:#166534;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;"> ✓ Verificación exitosa </p> <p style="margin:0;color:#14532d;font-size:13px;line-height:1.5;"> Si estás viendo este correo, la <b>cuenta de Microsoft Graph</b> y la <b>plantilla de correo</b> están correctamente configuradas. </p> </td> </tr> </table> <!-- Checklist de verificación --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Elementos verificados: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">✓</b> Conexión con el servidor SMTP </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">✓</b> Autenticación con las credenciales configuradas </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">✓</b> Envío de correo con formato HTML </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">✓</b> Entrega en la bandeja del destinatario </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">✓</b> Plantilla renderizada correctamente </td> </tr> </table> <!-- Nota final --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#eff6ff;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#1e40af;font-size:13px;line-height:1.5;"> <b>ℹ️ Nota:</b> Este es un correo de <b>prueba</b>. No requiere ninguna acción de tu parte. Puedes cerrarlo y continuar con tu trabajo. </p> </td> </tr> </table> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Mensaje de prueba generado desde la sección <b>Plantillas</b> de la configuración.<br/> Este correo no requiere acción y fue generado automáticamente. </p> </td> </tr> </table></div>' WHERE name_template = 'PRUEBA_ENVIO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(245,158,11,0.15);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (naranja calificación) --> <tr> <td style="background:#f59e0b;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de calificación --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#fffbeb;border:1px solid #fde68a;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#92400e;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ⭐ Califica tu experiencia </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> ¿Cómo fue tu experiencia con el ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span>? </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Tu ticket ha sido atendido y nos encantaría conocer tu opinión sobre el servicio recibido. Tu calificación nos ayuda a <b>mejorar continuamente</b> la atención. </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + estado --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#dcfce7;color:#166534;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> ✓ RESUELTO </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Agente --> <tr> <td style="padding:4px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Atendido por: </b> </td> <td style="padding:4px 0;color:#4b5563;"> {{agente}} </td> </tr> <!-- Área --> <tr> <td style="padding:4px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏢</span> Área: </b> </td> <td style="padding:4px 0;color:#4b5563;"> {{area}} </td> </tr> <!-- Fecha resolución --> <tr> <td style="padding:4px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de resolución: </b> </td> <td style="padding:4px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaResolucion}} </td> </tr> </table> </td> </tr> </table> <!-- Bloque destacado de calificación --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:28px 0;background:#fffbeb;border:2px dashed #f59e0b;border-radius:12px;"> <tr> <td style="padding:28px 24px;text-align:center;"> <p style="margin:0 0 12px;font-size:32px;letter-spacing:4px;line-height:1;"> ⭐⭐⭐⭐⭐ </p> <p style="margin:0 0 8px;color:#92400e;font-size:16px;font-weight:bold;"> Tu opinión nos ayuda a mejorar </p> <p style="margin:0 0 20px;color:#78350f;font-size:13px;line-height:1.5;"> Califica la atención recibida en menos de 1 minuto. Tu feedback es fundamental para el equipo de soporte. </p>  <p style="margin:16px 0 0;color:#92400e;font-size:11px;font-style:italic;"> Solo toma 1 minuto de tu tiempo </p> </td> </tr> </table> <!-- Qué evalúas --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> En la calificación podrás evaluar: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Cumplimiento de requerimientos</b> — ¿se resolvió lo solicitado? </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Tiempo de respuesta</b> — ¿fue oportuno el servicio? </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Calidad de la resolución</b> — ¿fue efectiva la solución? </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Comunicación del agente</b> — ¿fue clara y respetuosa? </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Satisfacción general</b> — ¿cómo calificas la experiencia? </td> </tr> </table> <!-- Alerta informativa --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#eff6ff;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#1e40af;font-size:13px;line-height:1.5;"> <b>ℹ️ Nota:</b> Tu calificación es <b>anónima</b>. Solo se usa con fines de mejora continua del servicio. </p> </td> </tr> </table> <!-- Botón CTA secundario --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#ec9811" style="border-radius:8px;"><a href="[urlCalificar]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Califica tu experiencia</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;text-align:center;"> ¡Gracias por tu tiempo y por ayudarnos a mejorar! </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tu ticket fue atendido y puedes calificar el servicio. </p> </td> </tr> </table></div>' WHERE name_template = 'RATING_REQUEST' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (azul info) --> <tr> <td style="background:#3b82f6;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de seguridad --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#1d4ed8;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 🔒 Seguridad </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Restablecimiento de contraseña </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Se ha restablecido tu contraseña de acceso a la <b>Mesa de Servicios</b>. Tu nueva <b>contraseña temporal</b> es: </p> <!-- Bloque de contraseña --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f9fafb;border:2px dashed #062e86;border-radius:10px;padding:20px;text-align:center;"> <p style="margin:0 0 8px;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:1px;font-weight:bold;"> Contraseña temporal </p> <p style="margin:0;font-family:''Courier New'',Consolas,monospace;font-size:24px;font-weight:bold;color:#062e86;letter-spacing:3px;word-break:break-all;"> [password] </p> </td> </tr> </table> <!-- Alerta de seguridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⚠️ Importante:</b> Por seguridad, al iniciar sesión deberás cambiar esta contraseña temporal por una personalizada. </p> </td> </tr> </table> <!-- Aviso si no solicitó el cambio --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef2f2;border-left:4px solid #dc2626;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#991b1b;font-size:13px;line-height:1.5;"> <b>¿No solicitaste este cambio?</b> Si no reconoces esta acción, contacta de inmediato al equipo de TI. Tu cuenta podría estar comprometida. </p> </td> </tr> </table> <!-- Pasos --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Cómo continuar: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">1.</b> Ingresa al sistema con tu correo corporativo. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">2.</b> Usa la contraseña temporal que aparece arriba. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">3.</b> Cambia la contraseña desde <b>Mi Perfil → Cambiar Contraseña</b>. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlLogin]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ingresar al sistema</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Por seguridad, te recomendamos <b>no compartir esta contraseña</b> con nadie y cambiarla inmediatamente después de iniciar sesión. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Si no reconoces esta acción, contacta al equipo de TI inmediatamente. </p> </td> </tr> </table></div>' WHERE name_template = 'RESET_PASSWORD' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(220,38,38,0.15);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (rojo crítico) --> <tr> <td style="background:#dc2626;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge crítico --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#fee2e2;border:1px solid #fecaca;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#991b1b;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 🚨 SLA vencido </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#dc2626;font-size:22px;font-weight:bold;line-height:1.3;"> El SLA del ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> ha vencido </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> El ticket que tienes asignado ha <b>superado el tiempo de SLA establecido</b> sin ser resuelto. Es necesario tomar acción <b>de inmediato</b> para evitar un mayor impacto en el servicio. </p> <!-- Indicador visual: SLA al 100% --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background:#fef2f2;border:1px solid #fecaca;border-radius:10px;"> <tr> <td style="padding:22px;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-size:12px;font-weight:bold;color:#991b1b;text-transform:uppercase;letter-spacing:0.5px;"> Tiempo de SLA consumido </td> <td align="right" style="font-size:22px;font-weight:bold;color:#dc2626;"> 100% </td> </tr> </table> <!-- Barra de progreso llena --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fecaca;border-radius:10px;height:12px;margin-bottom:16px;"> <tr> <td style="background:#dc2626;border-radius:10px;height:12px;width:100%;">&nbsp;</td> </tr> </table> <!-- Tiempos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;"> <tr> <td style="padding:4px 0;width:50%;"> <b style="color:#7f1d1d;">⏱️ Tiempo total del SLA:</b> </td> <td style="padding:4px 0;color:#4b5563;text-align:right;"> {{tiempoTotal}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#7f1d1d;">⌛ Vencido hace:</b> </td> <td style="padding:4px 0;color:#dc2626;font-weight:bold;text-align:right;"> {{tiempoVencido}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#7f1d1d;">📅 Debió resolverse:</b> </td> <td style="padding:4px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;text-align:right;"> {{fechaLimite}} </td> </tr> </table> </td> </tr> </table> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <tr> <td style="padding:4px 0;width:40%;"> <b style="color:#374151;">Solicitante:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{solicitante}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Área:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{area}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Estado:</b> </td> <td style="padding:4px 0;"> <span style="display:inline-block;padding:3px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Asignado a:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{agente}} </td> </tr> </table> </td> </tr> </table> <!-- Alerta crítica --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#dc2626;border-radius:8px;padding:16px 18px;"> <p style="margin:0;color:#ffffff;font-size:14px;line-height:1.5;font-weight:bold;"> 🚨 Acción inmediata requerida </p> <p style="margin:8px 0 0;color:#fecaca;font-size:13px;line-height:1.5;"> El incumplimiento del SLA afecta directamente los indicadores del equipo. Por favor, <b style="color:#ffffff;">atiende este ticket ahora</b> o escálalo a un supervisor. </p> </td> </tr> </table> <!-- Opciones de acción --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Acciones recomendadas: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#dc2626;">1.</b> <b>Atender el ticket de inmediato</b> y actualizar el estado. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#dc2626;">2.</b> <b>Escalar a un supervisor</b> si no puedes resolverlo. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#dc2626;">3.</b> <b>Documentar el motivo del retraso</b> en el ticket. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#dc2626;">4.</b> <b>Informar al solicitante</b> sobre la situación actual. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#dc2626" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Atender ticket incumplido</a></td></tr></table>  <!-- Nota de escalado automático --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⚡ Nota:</b> Si el ticket no se atiende en las próximas <b>2 horas</b>, se enviará una notificación al supervisor del equipo. </p> </td> </tr> </table> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Es una notificación crítica sobre el cumplimiento del SLA. </p> </td> </tr> </table></div>' WHERE name_template = 'SLA_BREACHED' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (naranja urgente) --> <tr> <td style="background:#f59e0b;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de urgencia --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#fff7ed;border:1px solid #fed7aa;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#c2410c;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ⚠️ SLA por vencer </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> El SLA del ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> está por vencer </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> El ticket que tienes asignado ha alcanzado el <b>{{porcentaje}}%</b> del tiempo de SLA establecido. Es necesario atenderlo <b>cuanto antes</b> para evitar incumplir el servicio. </p> <!-- Indicador visual del progreso del SLA --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:22px;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-size:12px;font-weight:bold;color:#374151;text-transform:uppercase;letter-spacing:0.5px;"> Tiempo de SLA consumido </td> <td align="right" style="font-size:18px;font-weight:bold;color:#f59e0b;"> {{porcentaje}}% </td> </tr> </table> <!-- Barra de progreso --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#e5e7eb;border-radius:10px;height:12px;margin-bottom:16px;"> <tr> <td style="background:#f59e0b;border-radius:10px;height:12px;width:{{porcentaje}}%;">&nbsp;</td> <td>&nbsp;</td> </tr> </table> <!-- Tiempos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;"> <tr> <td style="padding:4px 0;width:50%;"> <b style="color:#374151;">⏱️ Tiempo transcurrido:</b> </td> <td style="padding:4px 0;color:#4b5563;text-align:right;"> {{tiempoTranscurrido}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">⏰ Tiempo restante:</b> </td> <td style="padding:4px 0;color:#dc2626;font-weight:bold;text-align:right;"> {{tiempoRestante}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">🎯 Fecha límite:</b> </td> <td style="padding:4px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;text-align:right;"> {{fechaLimite}} </td> </tr> </table> </td> </tr> </table> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <tr> <td style="padding:4px 0;width:40%;"> <b style="color:#374151;">Solicitante:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{solicitante}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Área:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{area}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Estado:</b> </td> <td style="padding:4px 0;"> <span style="display:inline-block;padding:3px 10px;background:#fef3c7;color:#92400e;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> </table> </td> </tr> </table> <!-- Alerta de urgencia --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef2f2;border-left:4px solid #dc2626;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#991b1b;font-size:13px;line-height:1.5;"> <b>🚨 Acción requerida:</b> Atiende este ticket <b>inmediatamente</b>. Si no puedes resolverlo en el tiempo restante, considera <b>escalarlo</b> a un supervisor o reasignarlo. </p> </td> </tr> </table> <!-- Opciones de acción --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> ¿Qué puedes hacer? </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Resolver el ticket</b> en el tiempo restante. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Actualizar el estado</b> para reflejar el progreso actual. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Escalar o reasignar</b> si no puedes atenderlo a tiempo. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#f59e0b;">•</b> <b>Informar al solicitante</b> sobre el avance del caso. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#d97706" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Atender ticket</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Recibirás otra notificación si el SLA se vence sin resolver el ticket. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tienes un ticket próximo a vencer su SLA. </p> </td> </tr> </table></div>' WHERE name_template = 'SLA_WARNING' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (azul info) --> <tr> <td style="background:#3b82f6;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de tarea --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#1d4ed8;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 📋 Nueva tarea </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Se te ha asignado una nueva tarea </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Se te ha asignado una nueva tarea en la <b>Mesa de Servicios</b>. A continuación encontrarás el detalle: </p> <!-- Tarjeta de la tarea --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- Título de la tarea --> <p style="margin:0 0 14px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Descripción --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;"> <tr> <td style="padding:10px 12px;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <p style="margin:0;font-size:13px;color:#4b5563;line-height:1.5;"> {{descripcion}} </p> </td> </tr> </table> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Fecha inicio --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de inicio: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaInicio}} </td> </tr> <!-- Fecha fin --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏁</span> Fecha límite: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaFin}} </td> </tr> <!-- Duración --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">⏱️</span> Duración estimada: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{duracion}} minutos </td> </tr> <!-- Prioridad --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🎯</span> Prioridad: </b> </td> <td style="padding:6px 0;"> <span style="display:inline-block;padding:3px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> <!-- Asignada por --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Asignada por: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{asignadaPor}} </td> </tr> </table> </td> </tr> </table> <!-- Alerta según prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⏰ Recuerda:</b> Marca la tarea como <b>completada</b> en el sistema una vez finalizada, para mantener tus métricas al día. </p> </td> </tr> </table> <!-- Recomendaciones --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Recomendaciones: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">•</b> Revisa el detalle de la tarea antes de comenzar. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">•</b> Si necesitas más información, contacta al asignador. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">•</b> Actualiza el estado conforme avances. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ver ticket</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Puedes ver todas tus tareas asignadas en <b>Actividades → Mis tareas</b>. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tienes tareas asignadas en la Mesa de Servicios. </p> </td> </tr> </table></div>' WHERE name_template = 'TASK_ASIGNADA' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (azul info) --> <tr> <td style="background:#3b82f6;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de actualización --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#1d4ed8;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 🔔 Ticket actualizado </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> actualizado </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Tu ticket ha sido <b>actualizado</b>. Aquí tienes el detalle del cambio: </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#dbeafe;color:#1e40af;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <tr> <td style="padding:4px 0;width:40%;"> <b style="color:#374151;">Área:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{area}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Categoría:</b> </td> <td style="padding:4px 0;color:#4b5563;"> {{categoria}} </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Estado actual:</b> </td> <td style="padding:4px 0;"> <span style="display:inline-block;padding:3px 10px;background:#dbeafe;color:#1e40af;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> <tr> <td style="padding:4px 0;"> <b style="color:#374151;">Fecha de actualización:</b> </td> <td style="padding:4px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaActualizacion}} </td> </tr> </table> </td> </tr> </table> <!-- Detalle del cambio --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Detalle del cambio: </p> <!-- Tabla de cambio (antes → después) --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:16px 0;"> <tr> <td style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px 0 0 8px;padding:14px 16px;width:50%;vertical-align:top;"> <p style="margin:0 0 4px;color:#991b1b;font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;"> Antes </p> <p style="margin:0;color:#7f1d1d;font-size:13px;line-height:1.5;word-break:break-word;"> {{valorAnterior}} </p> </td> <td style="background:#f0fdf4;border:1px solid #bbf7d0;border-left:none;border-radius:0 8px 8px 0;padding:14px 16px;width:50%;vertical-align:top;"> <p style="margin:0 0 4px;color:#166534;font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;"> Ahora </p> <p style="margin:0;color:#14532d;font-size:13px;line-height:1.5;word-break:break-word;"> {{valorNuevo}} </p> </td> </tr> </table> <!-- Comentario del cambio (opcional) --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f9fafb;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0 0 4px;color:#1e40af;font-size:12px;font-weight:bold;"> Comentario del agente: </p> <p style="margin:0;color:#4b5563;font-size:13px;line-height:1.5;font-style:italic;"> "{{comentario}}" </p> </td> </tr> </table> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> ¿Qué puedes hacer ahora? </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">•</b> Revisar el ticket completo en el sistema. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">•</b> Responder con información adicional si es necesario. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#062e86;">•</b> Adjuntar archivos o capturas que ayuden a resolver el caso. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ver cambios del ticket</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Recibirás más notificaciones cuando tu ticket cambie de estado o reciba una nueva respuesta. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tienes un ticket activo en la Mesa de Servicios. </p> </td> </tr> </table></div>' WHERE name_template = 'TICKET_ACTUALIZADO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (azul primary) --> <tr> <td style="background:#3b82f6;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de asignación --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#1d4ed8;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 👤 Ticket asignado </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> asignado </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Se te ha asignado el siguiente ticket para su atención. A continuación encontrarás el detalle completo: </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Descripción --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;"> <tr> <td style="padding:10px 12px;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <p style="margin:0;font-size:13px;color:#4b5563;line-height:1.5;"> {{descripcion}} </p> </td> </tr> </table> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Solicitante --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Solicitante: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{solicitante}} </td> </tr> <!-- Área --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏢</span> Área: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{area}} </td> </tr> <!-- Categoría --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏷️</span> Categoría: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{categoria}} </td> </tr> <!-- Estado --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📌</span> Estado actual: </b> </td> <td style="padding:6px 0;"> <span style="display:inline-block;padding:3px 10px;background:#dbeafe;color:#1e40af;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> <!-- Fecha de asignación --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de asignación: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaAsignacion}} </td> </tr> <!-- Asignado por --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👔</span> Asignado por: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{asignadoPor}} </td> </tr> </table> </td> </tr> </table> <!-- Alerta según SLA --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"> <b>⏰ Atención:</b> Este ticket tiene un SLA de <b>{{slaTiempo}}</b>. Por favor, atiéndelo dentro del plazo para mantener el cumplimiento del servicio. </p> </td> </tr> </table> <!-- Pasos sugeridos --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Pasos sugeridos: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">1.</b> Revisa la descripción y adjuntos del ticket. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">2.</b> Contacta al solicitante si necesitas más información. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">3.</b> Actualiza el estado del ticket conforme avances. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#3b82f6;">4.</b> Marca el ticket como resuelto cuando termines. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ver ticket asignado</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Puedes ver todos tus tickets asignados en <b>Tickets → Mis asignados</b>. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tienes un ticket asignado en la Mesa de Servicios. </p> </td> </tr> </table></div>' WHERE name_template = 'TICKET_ASIGNADO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (gris neutro - cierre definitivo) --> <tr> <td style="background:#6b7280;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de cierre --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#f3f4f6;border:1px solid #d1d5db;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#374151;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> 🔒 Ticket cerrado </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Tu ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> ha sido cerrado </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Tu ticket ha sido <b>cerrado definitivamente</b>. Este correo sirve como <b>comprobante final</b> de la atención recibida. </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + estado cerrado --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#e5e7eb;color:#374151;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> 🔒 CERRADO </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Agente --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Atendido por: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{agente}} </td> </tr> <!-- Área --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏢</span> Área: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{area}} </td> </tr> <!-- Categoría --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏷️</span> Categoría: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{categoria}} </td> </tr> <!-- Fecha creación --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de creación: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaCreacion}} </td> </tr> <!-- Fecha cierre --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🔒</span> Fecha de cierre: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaCierre}} </td> </tr> <!-- Tiempo total --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">⏱️</span> Tiempo total: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{tiempoTotal}} </td> </tr> </table> </td> </tr> </table> <!-- Resumen de la atención --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f0fdf4;border-left:4px solid #16a34a;border-radius:6px;padding:14px 16px;"> <p style="margin:0 0 6px;color:#166534;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;"> 💡 Resumen de la atención </p> <p style="margin:0;color:#14532d;font-size:13px;line-height:1.5;"> {{resumenAtencion}} </p> </td> </tr> </table> <!-- Estadísticas del ticket --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Detalles finales: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;"> <tr> <td style="padding:14px 16px;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;"> <tr> <td style="padding:6px 0;width:60%;color:#6b7280;"> 📨 Total de mensajes intercambiados: </td> <td style="padding:6px 0;color:#374151;font-weight:bold;text-align:right;"> {{totalMensajes}} </td> </tr> <tr> <td style="padding:6px 0;color:#6b7280;"> 📎 Archivos adjuntos: </td> <td style="padding:6px 0;color:#374151;font-weight:bold;text-align:right;"> {{totalAdjuntos}} </td> </tr> <tr> <td style="padding:6px 0;color:#6b7280;"> 🔄 Cambios de estado: </td> <td style="padding:6px 0;color:#374151;font-weight:bold;text-align:right;"> {{totalCambios}} </td> </tr> </table> </td> </tr> </table> <!-- Invitación a calificar (solo si no calificó) --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:28px 0;background:#fffbeb;border:2px dashed #f59e0b;border-radius:12px;"> <tr> <td style="padding:24px;text-align:center;"> <p style="margin:0 0 8px;font-size:20px;"> ⭐⭐⭐⭐⭐ </p> <p style="margin:0 0 8px;color:#92400e;font-size:15px;font-weight:bold;"> Tu opinión es importante </p> <p style="margin:0 0 16px;color:#78350f;font-size:13px;line-height:1.5;"> Si aún no has calificado la atención recibida, puedes hacerlo ahora. Nos ayuda a mejorar continuamente. </p>  </td> </tr> </table> <!-- Alerta: reabrir ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#eff6ff;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#1e40af;font-size:13px;line-height:1.5;"> <b>ℹ️ ¿Necesitas más ayuda?</b> Si el problema vuelve a presentarse, puedes <b>crear un nuevo ticket</b> referenciando este caso (#{{id}}). </p> </td> </tr> </table> <!-- Acciones --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> También puedes: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#6b7280;">•</b> Consultar el historial completo del ticket. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#6b7280;">•</b> Descargar los adjuntos intercambiados. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#6b7280;">•</b> Guardar este correo como comprobante. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlNuevoTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Crear un ticket nuevo</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;text-align:center;"> Gracias por confiar en la <b>Mesa de Servicios</b> de COAC Magisterio de Pichincha. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tu ticket fue cerrado en la Mesa de Servicios. </p> </td> </tr> </table></div>' WHERE name_template = 'TICKET_CERRADO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (verde éxito) --> <tr> <td style="background:#16a34a;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de confirmación --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#166534;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ✅ Ticket creado </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Tu ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> ha sido registrado </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Hemos recibido tu solicitud correctamente. Nuestro equipo la atenderá a la brevedad. A continuación encontrarás el resumen del ticket: </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + prioridad --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> {{prioridad}} </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Descripción --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;"> <tr> <td style="padding:10px 12px;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;"> <p style="margin:0;font-size:13px;color:#4b5563;line-height:1.5;"> {{descripcion}} </p> </td> </tr> </table> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Área --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏢</span> Área: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{area}} </td> </tr> <!-- Categoría --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏷️</span> Categoría: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{categoria}} </td> </tr> <!-- Estado inicial --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📌</span> Estado: </b> </td> <td style="padding:6px 0;"> <span style="display:inline-block;padding:3px 10px;background:#dbeafe;color:#1e40af;font-size:11px;font-weight:bold;border-radius:12px;"> {{estado}} </span> </td> </tr> <!-- Fecha de creación --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de creación: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaCreacion}} </td> </tr> <!-- SLA estimado --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">⏱️</span> Tiempo de respuesta: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{slaTiempo}} </td> </tr> </table> </td> </tr> </table> <!-- Alerta informativa --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#eff6ff;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#1e40af;font-size:13px;line-height:1.5;"> <b>ℹ️ Siguiente paso:</b> Un agente será asignado a tu ticket en las próximas horas. Te notificaremos por correo cuando esto ocurra. </p> </td> </tr> </table> <!-- Qué puedes hacer --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> Mientras esperas, puedes: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Revisar el detalle completo del ticket en el sistema. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Agregar comentarios o archivos adicionales al ticket. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Consultar el estado en cualquier momento desde el sistema. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Contactar al equipo de soporte si es urgente. </td> </tr> </table> <!-- Botón CTA --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlTicket]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Ver ticket #{{id}}</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;"> Conserva este correo como comprobante de tu solicitud. Puedes ver todos tus tickets en <b>Mis tickets</b>. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque has creado un ticket en la Mesa de Servicios. </p> </td> </tr> </table></div>' WHERE name_template = 'TICKET_CREADO' AND custom_template = FALSE;
UPDATE notification_template SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"> <tr> <td align="center"> <!-- ============ CONTENEDOR PRINCIPAL ============ --> <table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(22,163,74,0.12);"> <!-- ============ HEADER ============ --> <tr> <td style="background:#062e86;padding:28px 32px;text-align:center;"> <table role="presentation" width="100%" cellpadding="0" cellspacing="0"> <tr> <td align="center" style="padding-bottom:12px;"> [logo] </td> </tr> <tr> <td align="center"> <p style="margin:0;color:#ffffff;font-size:18px;font-weight:bold;letter-spacing:0.5px;"> Mesa de Servicios </p> <p style="margin:6px 0 0;color:#c7d2fe;font-size:12px;letter-spacing:0.3px;"> COAC Magisterio de Pichincha </p> </td> </tr> </table> </td> </tr> <!-- Línea decorativa con acento (verde éxito) --> <tr> <td style="background:#16a34a;height:4px;line-height:4px;font-size:0;">&nbsp;</td> </tr> <!-- ============ CONTENIDO ============ --> <tr> <td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"> <!-- Badge de resolución --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"> <tr> <td style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:20px;padding:6px 14px;"> <p style="margin:0;color:#166534;font-size:12px;font-weight:bold;letter-spacing:0.5px;text-transform:uppercase;"> ✅ Ticket resuelto </p> </td> </tr> </table> <h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;"> Tu ticket #<span style="font-family:''Courier New'',Consolas,monospace;">{{id}}</span> ha sido resuelto </h1> <p style="margin:0 0 14px;"> Estimado/a <b style="color:#111827;">[nombre]</b>: </p> <p style="margin:0 0 20px;"> Nos complace informarte que tu ticket ha sido <b style="color:#16a34a;">resuelto</b> por nuestro equipo. A continuación encontrarás el resumen de la atención: </p> <!-- Tarjeta del ticket --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;"> <tr> <td style="padding:20px 22px;"> <!-- #id + estado resuelto --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:12px;"> <tr> <td style="font-family:''Courier New'',Consolas,monospace;font-size:14px;font-weight:bold;color:#6b7280;"> #{{id}} </td> <td align="right"> <span style="display:inline-block;padding:4px 10px;background:#dcfce7;color:#166534;font-size:11px;font-weight:bold;border-radius:12px;letter-spacing:0.5px;"> ✓ RESUELTO </span> </td> </tr> </table> <!-- Título --> <p style="margin:0 0 12px;font-size:16px;font-weight:bold;color:#111827;line-height:1.4;"> {{titulo}} </p> <!-- Metadatos --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:12px;"> <!-- Agente --> <tr> <td style="padding:6px 0;width:40%;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">👤</span> Atendido por: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{agente}} </td> </tr> <!-- Área --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏢</span> Área: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{area}} </td> </tr> <!-- Categoría --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">🏷️</span> Categoría: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{categoria}} </td> </tr> <!-- Fecha de resolución --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">📅</span> Fecha de resolución: </b> </td> <td style="padding:6px 0;color:#4b5563;font-family:''Courier New'',Consolas,monospace;font-size:12px;"> {{fechaResolucion}} </td> </tr> <!-- Tiempo total --> <tr> <td style="padding:6px 0;"> <b style="color:#374151;"> <span style="display:inline-block;width:16px;">⏱️</span> Tiempo total: </b> </td> <td style="padding:6px 0;color:#4b5563;"> {{tiempoTotal}} </td> </tr> </table> </td> </tr> </table> <!-- Solución aplicada --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#f0fdf4;border-left:4px solid #16a34a;border-radius:6px;padding:14px 16px;"> <p style="margin:0 0 6px;color:#166534;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:0.5px;"> 💡 Solución aplicada </p> <p style="margin:0;color:#14532d;font-size:13px;line-height:1.5;"> {{solucion}} </p> </td> </tr> </table> <!-- Alerta informativa --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"> <tr> <td style="background:#eff6ff;border-left:4px solid #3b82f6;border-radius:6px;padding:14px 16px;"> <p style="margin:0;color:#1e40af;font-size:13px;line-height:1.5;"> <b>ℹ️ ¿El problema persiste?</b> Si el problema aún no está resuelto, puedes <b>reabrir el ticket</b> desde el sistema indicando lo que falta. </p> </td> </tr> </table> <!-- Invitación a calificar --> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:28px 0;background:#fffbeb;border:2px dashed #f59e0b;border-radius:12px;"> <tr> <td style="padding:24px;text-align:center;"> <p style="margin:0 0 8px;font-size:20px;"> ⭐⭐⭐⭐⭐ </p> <p style="margin:0 0 8px;color:#92400e;font-size:15px;font-weight:bold;"> ¿Cómo fue tu experiencia? </p> <p style="margin:0 0 16px;color:#78350f;font-size:13px;line-height:1.5;"> Tu opinión nos ayuda a mejorar el servicio. Califica la atención recibida en menos de 1 minuto. </p>  </td> </tr> </table> <!-- Acciones disponibles --> <p style="margin:24px 0 12px;color:#062e86;font-size:14px;font-weight:bold;"> También puedes: </p> <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;"> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Ver el historial completo de la conversación. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Consultar los adjuntos intercambiados. </td> </tr> <tr> <td style="padding:8px 0;font-size:14px;color:#4b5563;line-height:1.5;"> <b style="color:#16a34a;">•</b> Descargar el comprobante del ticket resuelto. </td> </tr> </table> <!-- Botón CTA secundario --> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#ec9811" style="border-radius:8px;"><a href="[urlCalificar]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Calificar la atención</a></td></tr></table>  <p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;text-align:center;"> Gracias por confiar en la <b>Mesa de Servicios</b> de COAC Magisterio de Pichincha. </p> </td> </tr> <!-- ============ FOOTER ============ --> <tr> <td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"> <p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;letter-spacing:0.3px;"> Mesa de Servicios </p> <p style="margin:0 0 4px;color:#c7d2fe;font-size:12px;"> Servicio de soporte técnico </p> <p style="margin:0 0 12px;color:#aec0dd;font-size:12px;"> COAC Magisterio de Pichincha </p> <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto;"> <tr> <td style="padding:0 8px;"> <a href="[sitioWeb]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Sitio web </a> </td> <td style="color:#4a5b8f;font-size:11px;">|</td> <td style="padding:0 8px;"> <a href="[soporte]" style="color:#c7d2fe;font-size:11px;text-decoration:none;"> Soporte </a> </td> </tr> </table> <p style="margin:14px 0 0;color:#7c8bb5;font-size:11px;line-height:1.4;"> © 2026 COAC Magisterio de Pichincha.<br/> Todos los derechos reservados. </p> </td> </tr> </table> <!-- /Contenedor principal --> <!-- Nota de correo automático --> <p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;line-height:1.5;"> Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br/> Recibes este correo porque tu ticket fue marcado como resuelto. </p> </td> </tr> </table></div>' WHERE name_template = 'TICKET_RESUELTO' AND custom_template = FALSE;


-- ===== PLANTILLA DE CORREO DE PRUEBA =====
-- No la dispara ningún evento: sirve para comprobar que Microsoft Graph está
-- configurado y que el envío sale con el estilo de la marca. El destinatario se
-- toma de recipient_email (regla CUSTOM) o del propio usuario que la prueba.
INSERT INTO notification_template (name_template, type_template, subject_template, body_template,
                                   active_template, recipient_rule, recipient_email, icon_template, color_template) VALUES
    ('PRUEBA_ENVIO',
     'TICKET',
     'Prueba de envío de correo',
     '<div style="margin:0;padding:24px;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;">
   <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">
     <tr>
       <td style="background:#062e86;padding:20px 24px;color:#ffffff;">
         <div style="font-size:18px;font-weight:bold;">Mesa de Ayuda</div>
         <div style="font-size:12px;opacity:0.85;margin-top:4px;">Prueba de configuración de correo</div>
       </td>
     </tr>
     <tr>
       <td style="padding:24px;color:#1f2937;font-size:14px;line-height:1.6;">
         <p style="margin:0 0 12px;">Este mensaje confirma que el envío de correo está funcionando correctamente.</p>
         <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:16px;">
           <tr>
             <td style="padding:12px 16px;font-size:13px;">
               <strong>Enviado:</strong> [fecha] [hora]<br/>
               <strong>Usuario:</strong> [nombre]<br/>
               <strong>Correo:</strong> [email]
             </td>
           </tr>
         </table>
         <p style="margin:0;color:#6b7280;font-size:12px;">Si recibiste este correo, la cuenta de Microsoft Graph y la plantilla estan bien configuradas.</p>
       </td>
     </tr>
     <tr>
       <td style="background:#f9fafb;padding:16px 24px;color:#9ca3af;font-size:11px;text-align:center;">
         Mensaje de prueba generado desde la seccion Plantillas.
       </td>
     </tr>
   </table>
 </div>',
     TRUE,
     'CUSTOM',
     NULL,
     'fa-solid fa-paper-plane',
     '#062e86')
ON CONFLICT (name_template) DO NOTHING;

UPDATE notification_template SET icon_template = 'fa-solid fa-paper-plane', color_template = '#062e86'
WHERE name_template = 'PRUEBA_ENVIO' AND (icon_template IS NULL OR color_template IS NULL);

-- ===== CONFIGURACIÓN DE MARCA (BRANDING) =====
-- Sin imagen de fondo: el login tiene el suyo propio. Antes se sembraba
-- /uploads/publico/fondo.jfif, que solo existe en la carpeta uploads de
-- desarrollo (no está en el repositorio): una instalación nueva pedía una
-- imagen inexistente. Además un UPDATE lo volvía a poner en cada arranque si
-- un administrador lo quitaba. La imagen se sube en Admin → Marca → Imágenes.
INSERT INTO branding_config (logo_url, background_url, primary_color, secondary_color)
SELECT NULL, NULL, '#062e86', '#ec9811'
WHERE NOT EXISTS (SELECT 1 FROM branding_config);
