-- ============================================================================
-- SEMILLA DE PAGINAS DE ERROR Y POLITICA DE PRIVACIDAD
-- ============================================================================
-- Los textos por defecto se siembran solo si no existe la fila, de modo que un
-- servidor recien instalado ya muestra pantallas de error coherentes. En un
-- servidor que ya tiene la tabla, esto no hace nada: los textos que haya
-- guardado el super administrador se respetan.
--
-- Nota sobre el cuerpo de la politica: se arma con "||" y no con literales
-- E'...' pegados uno detras de otro. PostgreSQL solo concatena literales
-- adyacentes cuando son cadenas simples; los literales con escapes E'...'
-- cuentan como tokens independientes y el script falla con un error de
-- sintaxis en la segunda linea.

INSERT INTO error_page_config (id_error_page)
SELECT '00000000-0000-0000-0000-000000000004'
WHERE NOT EXISTS (SELECT 1 FROM error_page_config WHERE id_error_page = '00000000-0000-0000-0000-000000000004');

-- Red de seguridad para bases ya migradas en las que la fila llegara a existir
-- con textos nulos: los NOT NULL del esquema evitarian el insert, pero si alguien
-- los dejo a null a mano, la pantalla se quedaria sin texto. Se completa aqui.
UPDATE error_page_config
SET error_404_title   = COALESCE(NULLIF(TRIM(error_404_title), ''), 'Página no encontrada'),
    error_404_message = COALESCE(NULLIF(TRIM(error_404_message), ''), 'La dirección que buscas no existe o fue movida. Revisa el enlace o vuelve al inicio.'),
    error_404_icon    = COALESCE(NULLIF(TRIM(error_404_icon), ''), 'fa-solid fa-compass'),
    error_404_color   = COALESCE(NULLIF(TRIM(error_404_color), ''), '#64748b'),
    error_403_title   = COALESCE(NULLIF(TRIM(error_403_title), ''), 'Acceso no autorizado'),
    error_403_message = COALESCE(NULLIF(TRIM(error_403_message), ''), 'Tu perfil no tiene permiso para ver esta sección. Si crees que es un error, solicita el acceso al administrador.'),
    error_403_icon    = COALESCE(NULLIF(TRIM(error_403_icon), ''), 'fa-solid fa-lock'),
    error_403_color   = COALESCE(NULLIF(TRIM(error_403_color), ''), '#d97706'),
    error_500_title   = COALESCE(NULLIF(TRIM(error_500_title), ''), 'Error interno del servidor'),
    error_500_message = COALESCE(NULLIF(TRIM(error_500_message), ''), 'Ocurrió un problema inesperado en el servidor. El equipo técnico ya fue notificado.'),
    error_500_icon    = COALESCE(NULLIF(TRIM(error_500_icon), ''), 'fa-solid fa-triangle-exclamation'),
    error_500_color   = COALESCE(NULLIF(TRIM(error_500_color), ''), '#dc2626'),
    error_503_title   = COALESCE(NULLIF(TRIM(error_503_title), ''), 'Servicio no disponible'),
    error_503_message = COALESCE(NULLIF(TRIM(error_503_message), ''), 'El sistema está temporalmente fuera de servicio por mantenimiento. Vuelve a intentar en unos minutos.'),
    error_503_icon    = COALESCE(NULLIF(TRIM(error_503_icon), ''), 'fa-solid fa-screwdriver-wrench'),
    error_503_color   = COALESCE(NULLIF(TRIM(error_503_color), ''), '#2563eb')
WHERE id_error_page = '00000000-0000-0000-0000-000000000004';

-- Borrador de la politica de privacidad. Es una plantilla con la estructura que
-- normalmente exige la normativa, no un texto legal aprobado: el panel avisa de
-- que es un borrador y el super administrador lo sustituye por el documento real.
-- Al guardarlo desde el panel, custom_privacy pasa a TRUE y este seed deja de
-- tocar el contenido para siempre.
INSERT INTO privacy_config (id_privacy_config, privacy_title, privacy_version, privacy_content, privacy_contact, privacy_effective, custom_privacy)
SELECT '00000000-0000-0000-0000-000000000005',
       'Política de privacidad',
       '1.0',
       E'# Política de privacidad\n'
    || E'\n'
    || E'> **Borrador.** Esta es una plantilla de trabajo con la estructura que\n'
    || E'> suele exigirse. Sustitúyala por el documento oficial aprobado por la\n'
    || E'> institución antes de publicarlo.\n'
    || E'\n'
    || E'## 1. Responsable del tratamiento\n'
    || E'\n'
    || E'Indique qué entidad es la responsable del tratamiento de los datos\n'
    || E'personales y a qué dirección de correo se puede escribir para cualquier\n'
    || E'consulta.\n'
    || E'\n'
    || E'## 2. Qué datos se recogen\n'
    || E'\n'
    || E'Describa las categorías de datos que el sistema registra: datos\n'
    || E'identificativos de la persona usuaria, datos de contacto corporativos, y\n'
    || E'el contenido de los tickets, adjuntos y conversaciones asociadas a la\n'
    || E'mesa de servicios.\n'
    || E'\n'
    || E'## 3. Para qué se usan\n'
    || E'\n'
    || E'Explique la finalidad: gestionar las solicitudes recibidas a través de la\n'
    || E'mesa de servicios y llevar el control de su atención y cierre.\n'
    || E'\n'
    || E'## 4. Base jurídica\n'
    || E'\n'
    || E'Indique la base jurídica del tratamiento conforme a la normativa\n'
    || E'vigente.\n'
    || E'\n'
    || E'## 5. Conservación\n'
    || E'\n'
    || E'Detalle durante cuánto tiempo se conservan los tickets, sus adjuntos y el\n'
    || E'historial de conversaciones.\n'
    || E'\n'
    || E'## 6. Destinatarios y transferencias\n'
    || E'\n'
    || E'Indique si los datos se comparten con terceros, en particular con servicios\n'
    || E'de correo corporativo, y bajo qué garantías.\n'
    || E'\n'
    || E'## 7. Derechos de la persona usuaria\n'
    || E'\n'
    || E'Enumere los derechos de acceso, rectificación, supresión, oposición y\n'
    || E'portabilidad, y el canal para ejercerlos.\n'
    || E'\n'
    || E'## 8. Cambios en esta política\n'
    || E'\n'
    || E'Indique que cualquier modificación se publicará en esta misma página. Se\n'
    || E'aconseja consignar aquí la fecha de entrada en vigor.',
       NULL,
       NULL,
       FALSE
WHERE NOT EXISTS (SELECT 1 FROM privacy_config WHERE id_privacy_config = '00000000-0000-0000-0000-000000000005');

-- ==================================================================
-- RESTABLECIMIENTO DE CONTRASEÑA: enlace en vez de contraseña
-- ==================================================================
-- Aplica el cuerpo nuevo de RESET_PASSWORD solo mientras siga siendo el de fábrica.
--
-- El filtro NO es `custom_template = FALSE` porque en esta instalación la
-- plantilla ya viene marcada como personalizada (se guardó alguna vez desde
-- /admin/templates) y con ese filtro el seed no tocaría nada. Se queda la
-- versión con el botón para quien la haya escrito a mano.
UPDATE notification_template
   SET body_template = '<div style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:32px 16px;"><tr><td align="center"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 12px rgba(6,46,134,0.08);"><tr><td style="background:#062e86;padding:28px 32px;text-align:center;">[logo]</td></tr><tr><td style="background:#f59e0b;height:4px;line-height:4px;font-size:0;">&nbsp;</td></tr><tr><td style="padding:36px 40px 20px;font-family:Arial,Helvetica,sans-serif;color:#374151;font-size:15px;line-height:1.6;"><h1 style="margin:0 0 16px;color:#062e86;font-size:22px;font-weight:bold;line-height:1.3;">Restablecer tu contraseña</h1><p style="margin:0 0 14px;">Estimado/a <b style="color:#111827;">[nombre]</b>:</p><p style="margin:0 0 16px;">Recibimos una solicitud para restablecer la contraseña de tu cuenta en la Mesa de Servicios.</p><p style="margin:0 0 8px;">Elige tú la nueva contraseña con el botón de abajo. El enlace es de <b>un solo uso</b> y vence en 24 horas.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px 0 4px;"><tr><td align="center" bgcolor="#062e86" style="border-radius:8px;"><a href="[urlReset]" target="_blank" style="display:inline-block;padding:13px 30px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;">Establecer mi nueva contraseña</a></td></tr></table><p style="margin:20px 0 0;font-size:13px;color:#6b7280;line-height:1.5;">Si el botón no funciona, copie esta dirección en su navegador:<br/><span style="word-break:break-all;">[urlReset]</span></p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:28px 0 0;background:#fef3c7;border-left:4px solid #f59e0b;border-radius:6px;"><tr><td style="padding:14px 18px;"><p style="margin:0;color:#92400e;font-size:13px;line-height:1.5;"><b>¿No solicitó esto?</b> Ignore el mensaje y no haga nada: su contraseña actual sigue vigente. Cuando abra el enlace se cerrarán todas sus sesiones abiertas.</p></td></tr></table></td></tr><tr><td style="background:#062e86;padding:24px 32px;text-align:center;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0 0 6px;color:#ffffff;font-weight:bold;font-size:14px;">Mesa de Servicios</p><p style="margin:0;color:#c7d2fe;font-size:12px;">Servicio de soporte técnico · COAC Magisterio de Pichincha</p><p style="margin:12px 0 0;color:#7c8bb5;font-size:11px;">© 2026 COAC Magisterio de Pichincha.</p></td></tr></table><p style="max-width:620px;margin:16px auto 0;text-align:center;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#9ca3af;">Este correo fue generado automáticamente; por favor no responda a este mensaje.</p></td></tr></table></div>'
 WHERE name_template = 'RESET_PASSWORD'
   AND body_template LIKE '%contraseña temporal%'
   AND body_template LIKE '%[password]%';

-- Interruptor del doble factor. Apagado por defecto: activarlo cambia
-- el login de todo el mundo, y eso debe ser una decision consciente del
-- super administrador, no un efecto colateral de un despliegue.
INSERT INTO mfa_setting (id_mfa_setting, mfa_enabled, issuer_mfa)
VALUES ('00000000-0000-0000-0000-000000000006', FALSE, 'Mesa de Servicios')
ON CONFLICT (id_mfa_setting) DO NOTHING;
